-- Si el resultado es el esperado, ejecuta el UPDATE
UPDATE videogames
SET playtime_hours = playtime_hours + 10
WHERE developer = 'Nintendo';

DELETE FROM tabla
WHERE condición;

DELETE FROM videogames WHERE year < 1990;
