DELETE FROM videogames WHERE playtime_hours > 1000;

-- Primero revisa qué vas a eliminar
SELECT * FROM videogames WHERE year < 1990;

-- Si estás conforme, ejecuta el DELETE
DELETE FROM videogames WHERE year < 1990;

