CREATE VIEW nombre_vista AS
SELECT columnas
FROM tabla
WHERE condición;

CREATE VIEW juegos_modernos AS
SELECT title, developer, year, playtime_hours
FROM videogames
WHERE year > 2010;


SELECT * FROM juegos_modernos;
SELECT title FROM juegos_modernos WHERE playtime_hours > 50;

CREATE VIEW catalogo AS
SELECT v.title, d.name AS developer, d.country, v.year
FROM videogames v
JOIN developers d ON v.developer_id = d.id;

SELECT * FROM catalogo WHERE country = 'Japón';

CREATE INDEX nombre_indice ON tabla(columna);

CREATE INDEX idx_videogames_year ON videogames(year);


CREATE INDEX idx_videogames_dev_year ON videogames(developer, year);

Este índice acelera consultas como:

- `WHERE developer = 'Nintendo'` (usa la primera columna)
- `WHERE developer = 'Nintendo' AND year > 2000` (usa ambas columnas)

Pero **no** ayuda con `WHERE year > 2000` solo (porque `year` no es la primera columna del índice).

https://www.aprendesql.dev/indices

SELECT title, year
FROM videogames
WHERE year = (SELECT MAX(year) FROM videogames);

SELECT columnas FROM tabla1
UNION
SELECT columnas FROM tabla2;


SELECT developer FROM videogames WHERE year < 2000
UNION
SELECT developer FROM videogames WHERE playtime_hours > 50;

SELECT developer FROM videogames WHERE year < 2000
UNION ALL
SELECT developer FROM videogames WHERE playtime_hours > 50;

SELECT developer FROM videogames WHERE year < 2015
INTERSECT
SELECT developer FROM videogames WHERE playtime_hours > 50;

SELECT developer FROM videogames WHERE year < 2015
EXCEPT
SELECT developer FROM videogames WHERE playtime_hours > 50;

Una **CTE** (Common Table Expression) es una consulta temporal con nombre que puedes definir antes de tu consulta principal usando la palabra clave `WITH`. Piensa en ella como una **variable** que almacena un resultado intermedio para usarlo después

WITH nombre_cte AS (
  SELECT ...
)
SELECT * FROM nombre_cte;

SELECT title, playtime_hours,
  SUM(playtime_hours) OVER() AS total_horas
FROM videogames;

SELECT title, developer, playtime_hours,
  SUM(playtime_hours) OVER(PARTITION BY developer) AS horas_del_dev
FROM videogames;

SELECT title, playtime_hours,
  ROW_NUMBER() OVER(ORDER BY playtime_hours DESC) AS posicion
FROM videogames;

